        for chunk in (3072,6144):
            arm=next(a for a in report['arms'] if a['archiveChunkBytes']==chunk);rawroot=rd/'collection-r1/raw-files/job/chunk-pair'/('chunk-'+str(chunk));load=rawroot/'load';cfg=js(load/'configuration.json');plan=js(load/'admission-plan.json');transport=js(load/'transport-observations.json');registration=js(rawroot/'registration.json');csvrows=table(load/'arrivals.csv');backlog=table(load/'backlog.csv')
