                end=int(row['reply_completion_offset_ns']);latency=end-int(row['scheduled_offset_ns']);require(latency>=0,'Negative latency');latencies.append(latency);reply_end.append(end);within+=end<=12800000000;order_ids.add(int(row['order_id']))
