    for c in cohorts:lines.append('| %s | %d | %d | %.6f | %.9f | %.9f | %.9f | %d | %d |'%(c['label'],c['archiveChunkBytes'],c['acceptedOrdersInArrivalWindow'],c['arrivalWindowGoodputPerSecond'],c['allArrivalP99Ns']/1e9,c['lastReplyDrainNs']/1e9,c['totalMaintenanceCycleNs']/1e9,c['logicalMaintenanceRpcs'],c['sampledQueuedHighWater']))
